// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address admin, uint256 seed) public {
        vm.assume(admin != address(0));
        // Set the admin for the contract
        c.isAdmin(admin); // This is a getter, not a setter. We need to set isAdmin via some function.
        // The contract C has no setter for isAdmin. The only way is through deployment.
        // Since we cannot modify C, we assume the test is about the behavior of onlyAdmin modifier.
        // The property: if msg.sender is not admin, newEmergencyOracle should revert.
        // For reference C: admin passes, non-admin reverts.
        // For mutant C: non-admin passes, admin reverts.
        // But the problem statement says after call the value differs. Actually the contract C has no state variable newEmergencyOracle.
        // It emits event. The difference must be in revert behavior.
        // Let's restructure: The test checks that caller that is admin succeeds.
        // Since we cannot set isAdmin, we will deploy a new contract with this admin set.
        // But we cannot modify C. So we use a workaround: use vm.prank to impersonate.
        // Actually the isAdmin mapping is initially empty. So no one is admin.
        // The reference: require(isAdmin[msg.sender]) => always reverts for anyone.
        // But the problem says after a call completes, state differs. That is contradictory because reference will always revert.
        // Wait: the bug is to invert check. So reference: only admin can call (revert if not). Mutant: only non-admin can call (revert if admin).
        // But since mapping is empty, reference always reverts. Mutant always succeeds for anyone (since isAdmin[msg.sender] == false, !isAdmin[msg.sender] == true).
        // So the difference is: reference always reverts, mutant always succeeds.
        // So the property: for any caller, newEmergencyOracle should revert.
        // But the problem says "after a call to newEmergencyOracle completes, the value of state variable newEmergencyOracle differs" - that seems misstated.
        // Actually looking at code: contract C does not have state variable newEmergencyOracle. It only emits event.
        // Likely the intended difference is that reference reverts for all callers (since no admin set) while mutant succeeds.
        // So the property: newEmergencyOracle should revert for any caller.
        vm.prank(admin);
        bool reverted = false;
        try c.newEmergencyOracle("test") {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == true);
    }
}

